/*Table structure for table `laporan_transaksi` */

DROP TABLE IF EXISTS `laporan_transaksi`;

CREATE TABLE `laporan_transaksi` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `jenis_type` varchar(255) DEFAULT NULL,
  `jenis_id` int(11) DEFAULT NULL COMMENT 'id jenisnya',
  `kasus_id` int(11) DEFAULT NULL,
  `shift_id` int(11) DEFAULT NULL,
  `template_id` int(11) DEFAULT NULL,
  `template_nama` varchar(255) DEFAULT NULL,
  `template_kode` varchar(255) DEFAULT NULL,
  `template_satuan` varchar(255) DEFAULT NULL,
  `template_harga` varchar(255) DEFAULT NULL,
  `template_kategori_id` varchar(255) DEFAULT NULL,
  `template_kategori` varchar(255) DEFAULT NULL,
  `farmasi_id` int(11) DEFAULT NULL,
  `item_farmasi_id` int(11) DEFAULT NULL,
  `item_farmasi_aktif` int(11) DEFAULT NULL,
  `farmasi_items_id` int(11) DEFAULT NULL,
  `farmasi_items_kadaluarsa` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `jumlah_masuk` int(11) DEFAULT NULL COMMENT '+stok',
  `jumlah_keluar` int(11) DEFAULT NULL COMMENT '-stok',
  `subtotal` varchar(255) DEFAULT NULL,
  `src_created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `key` (`jenis_type`,`jenis_id`,`template_id`,`template_kategori_id`,`farmasi_items_id`,`farmasi_items_kadaluarsa`,`src_created_at`,`kasus_id`,`shift_id`,`farmasi_id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

