/*Table structure for table `kasus` */

DROP TABLE IF EXISTS `kasus`;

CREATE TABLE `kasus` (
  `id` int(12) NOT NULL AUTO_INCREMENT,
  `judul_kasus` varchar(128) DEFAULT NULL,
  `nomor_kasus` varchar(48) DEFAULT NULL,
  `kelas_id` int(11) DEFAULT 1,
  `transaksi_masuk_detail_id` int(11) DEFAULT NULL COMMENT 'DEPRECATED',
  `pasien_id` int(11) DEFAULT NULL,
  `pasien_pembayaran_id` int(11) DEFAULT NULL,
  `sep_id` int(11) DEFAULT NULL COMMENT 'no sep yang sedang aktif',
  `kasus_id_ibu` int(11) DEFAULT NULL,
  `datangigd_at` timestamp NULL DEFAULT NULL,
  `layani_igd_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `created_by` int(12) DEFAULT NULL,
  `mrs_at` timestamp NULL DEFAULT NULL,
  `krs_alasan` varchar(256) DEFAULT NULL,
  `krs_status` varchar(256) DEFAULT NULL,
  `krs_bpjs` int(11) DEFAULT NULL,
  `krs_by` int(11) DEFAULT NULL,
  `krs_at` timestamp NULL DEFAULT NULL,
  `krs_keterangan` text DEFAULT NULL,
  `end_at` timestamp NULL DEFAULT NULL,
  `end_by` int(12) DEFAULT NULL,
  `judul_kasus_changed` int(1) DEFAULT NULL COMMENT '1 jika telah diganti 0 jika belom diganti',
  `diagnosa_awal` int(11) DEFAULT NULL,
  `is_baru` tinyint(4) DEFAULT NULL COMMENT 'set apakah ini kasus baru atau bukan untuk laporan pasien baru atau bukan',
  `last_lokasi_id` int(11) DEFAULT NULL,
  `last_update_kolaborator` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `nomor_kasus` (`nomor_kasus`),
  KEY `kelas` (`kelas_id`),
  KEY `pasien` (`pasien_id`),
  KEY `sep` (`sep_id`),
  KEY `id_ibu` (`kasus_id_ibu`),
  FULLTEXT KEY `fulltext` (`judul_kasus`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

